import java.util.Scanner;

public class CityBubbleSort {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] cities = new String[10];

        System.out.println("Enter names of 10 cities:");
        for (int i = 0; i < cities.length; i++) {
            cities[i] = sc.nextLine().trim();
        }

        // Bubble Sort Algorithm
        for (int i = 0; i < cities.length - 1; i++) {
            for (int j = 0; j < cities.length - 1 - i; j++) {
                if (cities[j].compareToIgnoreCase(cities[j + 1]) > 0) {
                    String temp = cities[j];
                    cities[j] = cities[j + 1];
                    cities[j + 1] = temp;
                }
            }
        }

        System.out.println("\nSorted Cities (Alphabetical Order):");
        for (int i = 0; i < cities.length; i++) {
            System.out.println((i + 1) + ". " + cities[i]);
        }
    }
}
/*
VARIABLE DESCRIPTION TABLE:
Variable Name | Data Type | Purpose
cities        | String[]  | Array holding 10 city names
temp          | String    | Temporary swap variable
i             | int       | Outer loop pass counter
j             | int       | Inner loop adjacent comparison counter
*/
