import java.util.Scanner;

public class StudentBinarySearch {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] names = {
            "Abhishek", "Ananya", "Debanjan", "Ipsita", "Priyanka",
            "Rahul", "Rohit", "Sneha", "Subham", "Tanmoy"
        };

        System.out.print("Enter student name to search: ");
        String target = sc.nextLine().trim();

        int low = 0, high = names.length - 1;
        int pos = -1;

        while (low <= high) {
            int mid = (low + high) / 2;
            int cmp = names[mid].compareToIgnoreCase(target);

            if (cmp == 0) {
                pos = mid;
                break;
            } else if (cmp < 0) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        if (pos != -1) {
            System.out.println("Search Successful! Found at index: " + pos);
        } else {
            System.out.println("Search Unsuccessful! Name not present in record.");
        }
    }
}
